import{_ as n,C as r,o as e,c as i,a2 as t,b as s,w as o,a as p,E as c,a3 as d}from"./chunks/framework.DToEn73J.js";const f=JSON.parse('{"title":"Agent Loop","description":"","frontmatter":{"title":"Agent Loop","chapter":"1.1","order":1,"summary":"Agent Loop 是 Agent 感知-思考-行动的驱动核心，本质是围绕 function-calling 的循环。"},"headers":[],"relativePath":"01-agent-basics/agent-loop.md","filePath":"01-agent-basics/agent-loop.md","lastUpdated":1788255095000}'),A={name:"01-agent-basics/agent-loop.md"};function h(E,a,g,u,_,m){const l=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="agent-loop" tabindex="-1">Agent Loop <a class="header-anchor" href="#agent-loop" aria-label="Permalink to &quot;Agent Loop&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>Agent Loop 是 Agent 持续「感知环境 → 模型推理 → 调用 Tool 改变环境」的驱动核心，把单次 LLM 补全扩展成可多步推进的自治过程。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p>主流实现基于 ReAct（Reason+Act）范式，落地为 function-calling loop：每轮把 System / 历史 Tool / User 消息拼成上下文发给模型，模型可返回文本或 tool_calls，运行时执行工具后把结果作为 <code>role: tool</code> 消息回填，进入下一轮，直到模型不再请求工具或触发终止条件。</p>',5)),(e(),s(d,null,{default:o(()=>[c(l,{id:"mermaid-15",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20U%20as%20User%0A%20%20%20%20participant%20L%20as%20Agent%20Loop%0A%20%20%20%20participant%20M%20as%20Model%0A%20%20%20%20participant%20T%20as%20Tool%0A%20%20%20%20U-%3E%3EL%3A%20%E6%8F%90%E4%BA%A4%20task%0A%20%20%20%20loop%20%E6%AF%8F%E8%BD%AE%E6%8E%A8%E7%90%86%0A%20%20%20%20%20%20%20%20L-%3E%3EM%3A%20System%20%2B%20history(tool%2Fuser)%20%E6%B6%88%E6%81%AF%0A%20%20%20%20%20%20%20%20M--%3E%3EL%3A%20text%20%2F%20tool_calls%0A%20%20%20%20%20%20%20%20alt%20%E6%9C%89%20tool_calls%0A%20%20%20%20%20%20%20%20%20%20%20%20L-%3E%3ET%3A%20%E6%89%A7%E8%A1%8C%E5%B7%A5%E5%85%B7%0A%20%20%20%20%20%20%20%20%20%20%20%20T--%3E%3EL%3A%20%E7%BB%93%E6%9E%84%E5%8C%96%E7%BB%93%E6%9E%9C%0A%20%20%20%20%20%20%20%20%20%20%20%20L-%3E%3EL%3A%20%E8%BF%BD%E5%8A%A0%20role%3Atool%20%E6%B6%88%E6%81%AF%0A%20%20%20%20%20%20%20%20else%20%E6%97%A0%20tool_calls%0A%20%20%20%20%20%20%20%20%20%20%20%20L--%3E%3EU%3A%20%E8%BF%94%E5%9B%9E%E6%9C%80%E7%BB%88%E7%BB%93%E6%9E%9C%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20end%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>关键设计：System 消息在整轮循环中恒定不变；Tool 结果以 <code>tool_call_id</code> 与请求对齐；User 消息仅首轮或中途注入。</p><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>没有显式 Loop，模型只能一次性作答，无法处理需多步检索、迭代或环境反馈的任务；但 Loop 本身不保证收敛，需配合后文 max_steps 与预算护栏（见 /01-agent-basics/budget-control）。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>把 Tool 结果当作 User 消息回填，破坏 <code>tool_call_id</code> 对齐，导致多轮调用后模型上下文错乱。</li><li>每轮都重发完整 System + 全量历史，未做 Context Window 裁剪，长任务极易溢出（见 /03-context-memory/context-window）。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li>OpenAI Agents SDK：Runner.run 内部即 <code>model → tools → append → repeat</code> 循环，直至无输出。<a href="https://openai.github.io/openai-agents-python/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/</a></li><li>LangGraph：以 StateGraph 节点显式表达 loop，支持条件边与中断恢复。<a href="https://langchain-ai.github.io/langgraph/" target="_blank" rel="noreferrer">https://langchain-ai.github.io/langgraph/</a></li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>/01-agent-basics/tool-abstraction</li><li>/01-agent-basics/structured-output</li><li>/01-agent-basics/budget-control</li><li>/03-context-memory/context-window</li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>',11))])}const L=n(A,[["render",h]]);export{f as __pageData,L as default};
